Algoritmo SumaFilas
  Dimension m[3, 3] Como Entero;
  Para f <- 0 Hasta 2 Hacer
    Para c <- 0 Hasta 2 Hacer
      Leer m[f, c];
    FinPara
  FinPara
  Para f <- 0 Hasta 2 Hacer
    Definir suma Como Entero <- 0;
    Para c <- 0 Hasta 2 Hacer
      suma <- suma + m[f, c];
    FinPara
    Escribir suma;
  FinPara
FinAlgoritmo
